import json

def parse_with_bounded_retry(raw_outputs: list[str]) -> dict:
    for attempt, payload in enumerate(raw_outputs, start=1):
        try:
            return json.loads(payload)
        except json.JSONDecodeError:
            if attempt == len(raw_outputs):
                raise ValueError(f'All {attempt} unconstrained JSON attempts failed')
    raise ValueError('Empty output stream')

from typing import Dict, Set

def step_dfa(transitions: Dict[tuple[int, str], int], state: int, ch: str) -> int:
    key = (state, ch)
    if key not in transitions:
        raise ValueError(f'Invalid character {ch!r} from DFA state {state}')
    return transitions[key]

import numpy as np

def build_state_bitmask(valid_token_ids: list[int], vocab_size: int = 128256) -> np.ndarray:
    if vocab_size <= 0:
        raise ValueError('vocab_size must be positive')
    num_words = (vocab_size + 31) // 32
    mask = np.zeros(num_words, dtype=np.uint32)
    for tid in valid_token_ids:
        if 0 <= tid < vocab_size:
            mask[tid >> 5] |= np.uint32(1 << (tid & 31))
    return mask

import numpy as np

def apply_logit_bitmask(logits: np.ndarray, bitmask: np.ndarray) -> np.ndarray:
    if logits.ndim != 1:
        raise ValueError('Expected 1D logit vector')
    masked = logits.copy()
    for tid in range(logits.shape[0]):
        if not ((bitmask[tid >> 5] >> (tid & 31)) & 1):
            masked[tid] = -np.inf
    return masked

def overlap_step_budget(gpu_forward_ms: float, cpu_fsm_us: float, h2d_copy_us: float) -> float:
    if gpu_forward_ms <= 0:
        raise ValueError('GPU forward pass must be positive')
    hidden_overhead_ms = (cpu_fsm_us + h2d_copy_us) / 1000.0
    return max(0.0, hidden_overhead_ms - gpu_forward_ms)

def classify_cfg_token(is_stack_sensitive: bool, cached_mask_hit: bool) -> str:
    if not is_stack_sensitive and cached_mask_hit:
        return 'O(1)_CACHED_BITMASK'
    if not is_stack_sensitive:
        return 'POPULATE_STATIC_MASK'
    return 'DYNAMIC_STACK_EVAL'
